mapper.update:
update defense_records
set video_url = #{videoUrl},
    updated_at = now()
where user_id = #{userId}
  and topic_id = #{topicId}

mapper.select:
select count(dr.defense_id)
from defense_records dr
where dr.user_id = #{userId}
  and dr.topic_id = #{topicId}

select user_id as userId
from users
where user_number = #{userNumber}

SELECT video_url FROM defense_records
WHERE user_id = #{userId} AND topic_id = #{topicId}
    LIMIT 1

select video_ppt_words, video_words
from defense_records
where topic_id = #{topicId}
